function adler32(bytes) {
  let a = 1, b = 0;
  for (let i = 0; i < bytes.length; i++) {
    a = (a + bytes[i]) % 65521;
    b = (b + a) % 65521;
  }
  return ((b << 16) | a) >>> 0;
}
function zlibStored(data) {
  const out = [0x78, 0x01];
  let offset = 0;
  while (offset < data.length) {
    const chunk = Math.min(65535, data.length - offset);
    const final = offset + chunk >= data.length ? 1 : 0;
    out.push(final);
    out.push(chunk & 0xFF, (chunk >> 8) & 0xFF);
    const nlen = (~chunk) & 0xFFFF;
    out.push(nlen & 0xFF, (nlen >> 8) & 0xFF);
    for (let i = 0; i < chunk; i++) out.push(data[offset + i]);
    offset += chunk;
  }
  const adler = adler32(data);
  out.push((adler >>> 24) & 0xFF, (adler >>> 16) & 0xFF, (adler >>> 8) & 0xFF, adler & 0xFF);
  return Uint8Array.from(out);
}
const STD = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const PLU = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_";
function plantumlEncode(text) {
  const zlib = zlibStored(new TextEncoder().encode(text));
  let bin = "";
  for (let i = 0; i < zlib.length; i++) bin += String.fromCharCode(zlib[i]);
  const b64 = btoa(bin);
  let out = "";
  for (const ch of b64) {
    if (ch === "=") continue;
    out += PLU[STD.indexOf(ch)];
  }
  return out;
}

// 1) Verify encoding round-trip via the server's txt endpoint
const test = "@startuml\nBob -> Alice : hello\n@enduml";
const r1 = await fetch("https://www.plantuml.com/plantuml/txt/" + plantumlEncode(test));
const decoded = await r1.text();
const roundTripOk = decoded === test;

// 2) Fetch the real C4-PlantUML diagram as PNG
const c4 = `@startuml
title <size:24>System Context View: Library</size>

set separator none
left to right direction

<style>
  root {
    BackgroundColor: #ffffff
    FontColor: #444444
  }
</style>

!include <C4/C4>
!include <C4/C4_Context>

Person(Patron, "Patron", $descr="Borrows books at the library.", $tags="", $link="")
System(Library, "Library", $descr="Manages books and loans.", $tags="", $link="")

Rel(Patron, Library, "Browses the catalogue through", $techn="HTTPS", $tags="", $link="")

SHOW_LEGEND(true)
hide stereotypes
@enduml`;
const r2 = await fetch("https://www.plantuml.com/plantuml/png/" + plantumlEncode(c4));
const buf = new Uint8Array(await r2.arrayBuffer());
let bin2 = "";
for (let i = 0; i < buf.length; i++) bin2 += String.fromCharCode(buf[i]);
return {
  roundTripOk,
  decodedTest: decoded,
  status: r2.status,
  type: r2.headers.get("content-type"),
  size: buf.length,
  magic: Array.from(buf.slice(0, 8)).map(b => b.toString(16)).join(" "),
  pngB64: btoa(bin2),
};

